<div class="d-flex justify-content-between mb-4"><h1 class="h3">Administradores</h1><a class="btn btn-primary" href="/usuarios/novo">Novo administrador</a></div><div class="table-responsive"><table class="table table-bordered bg-white align-middle"><thead><tr><th>Nome</th><th>E-mail</th><th>Status</th><th>Último login</th><th>Ações</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= htmlspecialchars($user['nome'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($user['email'], ENT_QUOTES, 'UTF-8') ?></td><td><?= $user['ativo'] ? 'Ativo' : 'Inativo' ?></td><td><?= htmlspecialchars($user['ultimo_login_em'] ?? 'Nunca', ENT_QUOTES, 'UTF-8') ?></td><td><a class="btn btn-sm btn-outline-primary" href="/usuarios/editar?id=<?= (int) $user['id'] ?>">Editar</a></td></tr><?php endforeach; ?><?php if (!$users): ?><tr><td colspan="5" class="text-center text-muted">Nenhum administrador cadastrado.</td></tr><?php endif; ?></tbody></table></div><a href="/dashboard">Voltar ao dashboard</a>
